   "lieu": "Francfort (Allemagne) ; Rotterdam et Heerenveen (Pays-Bas)",
   "resume": "« We Have Arrived » est écrit en 1990 à Francfort par Marc Acardipane (alias Marc Trauner, Mescalinum United) et paraît sur Planet Core Productions en 1990, puis sous licence chez Industrial Strength, le label du DJ new-yorkais Lenny Dee, en 1991. Wikipédia le dit « souvent considéré » comme le premier titre de hardcore techno : c'est une attribution, pas un fait établi. Aux Pays-Bas, Paul Elstak crée Rotterdam Records en 1992 (premier disque : Euromasters), puis ID&T organise le premier Thunderdome le 3 octobre 1992 à Heerenveen ; les compilations Thunderdome démarrent en 1993. Le gabber (140 à 190 BPM « généralement » selon Wikipédia EN ; le hardcore au sens large monte à 200 BPM et plus) est présenté par l'Institut néerlandais du son et de l'image comme le premier style de musique électronique « vraiment néerlandais ».",
   "compte": "C'est la naissance de la branche dure de la techno ; le hardstyle et le frenchcore s'en réclament, chacun avec d'autres influences.",
