   "titre": "Première Techno Parade à Paris",
   "lieu": "Paris (France)",
   "resume": "Le samedi 19 septembre 1998, la première Techno Parade de Paris réunit environ 200 000 personnes à un moment où la musique électronique était « diabolisée ». L'ancien ministre de la Culture Jack Lang en est l'initiateur ; il a assisté à la Love Parade de Berlin, qui lui sert de modèle, et s'entoure d'Henri Maurel, président de Radio FG et cofondateur de Technopol. Selon Wikipédia FR, cette première édition a conduit à une circulaire interministérielle (Culture, Intérieur, Défense) reconnaissant l'aspect culturel de la techno.",
   "compte": "C'est la première Techno Parade et une grande manifestation publique de la techno en France, trois ans après la circulaire de 1995.",
