   "titre": "Fabric : ouverture, fermeture forcée et réouverture",
   "lieu": "Farringdon, Londres (Royaume-Uni)",
   "resume": "Le club Fabric, fondé par Keith Reilly et Cameron Leslie, ouvre le 29 octobre 1999 à Farringdon (Londres), en face du marché de Smithfield. En septembre 2016, après deux décès liés à la drogue, le conseil d'Islington lui retire sa licence et la fermeture est annoncée comme définitive. Une campagne de soutien réunit plus de 200 000 livres pour un fonds juridique ; le 21 novembre 2016, un accord permet la réouverture avec des conditions plus strictes (pièce d'identité avec photo, surveillance, interdiction à vie pour les dealers, pas de moins de 19 ans du vendredi 20 h au lundi 8 h).",
   "compte": "L'affaire Fabric a montré la fragilité des clubs face aux licences et à la politique des drogues, et la capacité de la communauté à les défendre.",
