   "resume": "Les autorités ferment les clubs de Berlin à cause du coronavirus le vendredi précédant le 17 mars 2020. Le 18 mars 2020, la Clubcommission Berlin et la campagne Reclaim Club Culture lancent, avec ARTE Concert, la plateforme United We Stream : des DJ sets diffusés en direct depuis des clubs vides. Les spectateurs sont invités à un don volontaire (« Virtual Club Ticket ») dont tout le produit va à un fonds d'aide aux clubs, aux organisateurs et aux artistes.",
