   "resolution_fr": "Première édition : le samedi 1er juillet 1989 à Berlin-Ouest (1er juillet 1989 vérifié comme un samedi), avec environ 150 personnes derrière trois camions à plateau (taz : « rund 150 Menschen » ; Wikipédia DE et FR : environ 150 ; Europa-Center : « environ 150 personnes », trois camions, de Wittenbergplatz par l'Europa-Center jusqu'au Ku'damm). La page Wikipédia EN donne seulement « juillet 1989 » et 150 personnes. Fondateurs : l'initiative vient de Matthias Roeingh (Dr. Motte) et de Danielle de Picciotto, alors sa compagne (taz, Europa-Center, Wikipédia DE et EN). Wikipédia FR ajoute WestBam (Maximilian Lenz) comme cocréateur ; Wikipédia DE ne le cite qu'en 1991 comme intervenant sur un char, et taz et Europa-Center ne le mentionnent pas : WestBam n'est donc pas à compter comme fondateur. Wikipédia DE et EN attribuent à Miriam Scheffler, employée administrative, l'idée de déclarer la parade comme manifestation politique. Pour l'ancien chiffre de « 300 personnes » de la frise : non retrouvé dans les sources ouvertes ; 150 est le chiffre retenu.",
